def smallestHittingSquare(grid):
    m, n = len(grid), len(grid[0])
    P = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m):
        for j in range(n):
            P[i + 1][j + 1] = P[i][j + 1] + P[i + 1][j] - P[i][j] + grid[i][j]

    def safe(s):
        for i in range(m - s + 1):
            for j in range(n - s + 1):
                if P[i + s][j + s] - P[i][j + s] - P[i + s][j] + P[i][j] == 0:
                    return False
        return True

    hi = min(m, n)
    if not safe(hi):
        return -1
    lo = 1
    while lo < hi:
        mid = (lo + hi) // 2
        if safe(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo
